<script setup lang="ts">
import {ref} from 'vue';import {api,session,notify,isDemo} from '../api';import {resetDemo} from '../demo';import Icon from '../components/Icon.vue'
const name=ref(session.user?.name||''),phone=ref(session.user?.phone||''),busy=ref(false),currentPassword=ref(''),password=ref('');async function save(){busy.value=true;try{await api('/account','PUT',{name:name.value,phone:phone.value});session.user=await api('/auth/me');notify('Perfil actualizado')}catch(e:any){notify(e.message,'error')}finally{busy.value=false}}async function change(){try{await api('/account/password','POST',{currentPassword:currentPassword.value,password:password.value});session.user=null;location.hash='/login'}catch(e:any){notify(e.message,'error')}}
</script>
<template><div class="page-heading"><div><p class="eyebrow">TU ESPACIO PERSONAL</p><h1>Mi cuenta</h1><p class="muted">Mantén tu información al día.</p></div></div><div class="account-grid"><section class="panel"><div class="panel-heading"><h2>Información personal</h2><Icon name="users"/></div><form class="padded-form" @submit.prevent="save"><label>Nombre completo<input v-model="name" required maxlength="160"></label><label>Correo<input :value="session.user?.email" disabled></label><label>Teléfono<input v-model="phone" maxlength="30"></label><button class="btn primary" :disabled="busy">Guardar perfil</button></form></section><section class="panel"><div class="panel-heading"><h2>Seguridad</h2><Icon name="shield"/></div><div v-if="isDemo" class="padded-form"><div class="inventory-note">Este prototipo no utiliza contraseñas reales. Los accesos solo cambian el rol de demostración.</div><h3>Datos de demostración</h3><p class="muted">Puedes restaurar los vehículos, órdenes y piezas ficticios al estado inicial. Se perderán únicamente los cambios hechos en este prototipo.</p><button class="btn secondary" @click="resetDemo">Restablecer datos de ejemplo</button></div><form v-else class="padded-form" @submit.prevent="change"><label>Contraseña actual<input v-model="currentPassword" type="password" required autocomplete="current-password"></label><label>Nueva contraseña<input v-model="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><button class="btn primary">Cambiar contraseña</button></form></section></div></template>
